def get_total_number_of_sequences(m, n):
    def is_valid(k):
        if k < 1:
            return False
        if k % 2 == 0:
            return False
        if k > m:
            return False
        if k < 2:
            return False
        return True
    ans = 0
    for i in range(1, n + 1):
        if not is_valid(i):
            continue
        for j in range(1, n):
            if not is_valid(j):
                continue
            if i == 1:
                ans += 1
            else:
                if j == 1:
                    ans += 1
                else:
                    if i * j > m:
                        ans -= 1
    return ans

