        d = []
        for i in s:
            if i.isdigit():
                d.append(int(i))
        return d
    n = int(n)
    if n == 0:
        return 0
    d = get_digits(str(n))
    d.sort()
    ans = []
    for i in d:
        if i > 0:
            ans.append(i)
    return max(ans)

